// Package mail fetches a device's Fount Mail from the edge, checks every
// message against the boot that signed it, decrypts it with the device's key,
// accounts for every sequence number, and hands each message to the offline
// sender verifier (package verify) before the app sees it.
//
// The edge's side of each contract is in fount-mail-edge: the Device API in
// internal/deviceapi, the stored-message object and gap records in
// internal/store. testdata/edge-vectors.json is generated by that code.
package mail

import (
	"bytes"
	"crypto/ecdh"
	"crypto/ed25519"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
)

// Keys are one address's private keys, as far as reading its mail needs them.
type Keys struct {
	MailboxID  []byte
	Signing    ed25519.PrivateKey
	Decryption *ecdh.PrivateKey
}

// keysCredential is the body of the mail_keys credential. Each entry is a
// superset of edge internal/operator.RolePrivateKeys plus the mailbox id, so a
// role mailbox's key file works with "mailbox_id" added. Keys the broker
// doesn't need to read mail are accepted and dropped.
type keysCredential struct {
	Addresses []addressKeys `json:"addresses"`
}

type addressKeys struct {
	MailboxID     string `json:"mailbox_id"`
	SigningKey    []byte `json:"signing_key"`    // Ed25519 seed
	DecryptionKey []byte `json:"decryption_key"` // X25519 private key

	Role           string `json:"role,omitempty"`
	MailboxKey     []byte `json:"mailbox_key,omitempty"`
	OwnerChangeKey []byte `json:"owner_change_key,omitempty"`
	PasskeyKey     []byte `json:"passkey_key,omitempty"`
}

// MaxAddresses bounds one mail_keys credential.
const MaxAddresses = 1024

var ErrBadKeys = errors.New("mail: bad mail_keys credential")

// ParseKeys reads a mail_keys credential. An empty body clears the keys.
func ParseKeys(body []byte) (map[string]*Keys, error) {
	out := map[string]*Keys{}
	if len(body) == 0 {
		return out, nil
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	var c keysCredential
	if err := dec.Decode(&c); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrBadKeys, err)
	}
	if dec.More() {
		return nil, fmt.Errorf("%w: trailing data", ErrBadKeys)
	}
	if len(c.Addresses) > MaxAddresses {
		return nil, fmt.Errorf("%w: more than %d addresses", ErrBadKeys, MaxAddresses)
	}
	for i, a := range c.Addresses {
		id, err := hex.DecodeString(a.MailboxID)
		if err != nil || len(id) != 32 || hex.EncodeToString(id) != a.MailboxID {
			return nil, fmt.Errorf("%w: address %d: mailbox_id must be 64 lowercase hex characters", ErrBadKeys, i)
		}
		if len(a.SigningKey) != ed25519.SeedSize {
			return nil, fmt.Errorf("%w: address %d: signing_key must be a 32-byte Ed25519 seed", ErrBadKeys, i)
		}
		d, err := ecdh.X25519().NewPrivateKey(a.DecryptionKey)
		if err != nil {
			return nil, fmt.Errorf("%w: address %d: decryption_key must be a 32-byte X25519 key", ErrBadKeys, i)
		}
		if _, dup := out[a.MailboxID]; dup {
			return nil, fmt.Errorf("%w: address %d: mailbox %s listed twice", ErrBadKeys, i, a.MailboxID)
		}
		out[a.MailboxID] = &Keys{MailboxID: id, Signing: ed25519.NewKeyFromSeed(a.SigningKey), Decryption: d}
	}
	return out, nil
}

// keyring holds the current mail_keys. The app can replace it but never read it.
type keyring struct {
	mu   sync.RWMutex
	keys map[string]*Keys
}

func (k *keyring) set(m map[string]*Keys) {
	k.mu.Lock()
	defer k.mu.Unlock()
	k.keys = m
}

func (k *keyring) get(mailbox string) (*Keys, bool) {
	k.mu.RLock()
	defer k.mu.RUnlock()
	v, ok := k.keys[mailbox]
	return v, ok
}
